from app.main import app
from fastapi.testclient import TestClient

def test_root_get_idempotent_on_repeated_calls():
    client = TestClient(app)
    expected = {"message": "Welcome to Task Manager API", "docs": "/docs", "version": "1.0.0"}
    for _ in range(3):
        r = client.get("/")
        assert r.status_code == 200
        assert r.json() == expected

test_root_get_idempotent_on_repeated_calls()
